//! Checks 4 and 5: struct layouts and macro constants, as the real C compiler sees them.
//!
//! `rustssl-abi` was generated by bindgen and clang against stand-in libc headers (see codegen's
//! `headers.rs`). These checks compile C programs against the official headers with the host's
//! own compiler and C library, print every layout and every constant, and compare the output
//! with the generated Rust for the host target, which they read with `syn`.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs;
use std::path::PathBuf;
use std::process::Command;

use super::{Context, Outcome};
use crate::codegen::headers::Context as Headers;
use crate::test_c::cc;
use crate::util::{Result, run_output};

/// Check 4: every struct and union's size and alignment, and each field's offset.
pub fn layouts(cx: &Context) -> Result<Outcome> {
    let facts = layout_facts(&generated(cx)?)?;
    let headers = Headers::new(&cx.root, &cx.work.join("headers"))?;
    let records = record_tags(&run_output(
        cc().args(include_flags(cx))
            .args(["-std=gnu11", "-E"])
            .arg(&headers.wrapper),
    )?);

    let mut program = String::from("#include <stddef.h>\n#include <stdio.h>\n");
    writeln!(
        program,
        "#include \"{}\"\n\nint main(void)\n{{",
        headers.wrapper.display()
    )?;
    let mut checked = 0;
    for (label, _) in &facts {
        let Some(fact) = Fact::parse(label) else {
            continue;
        };
        let ty = c_type(fact.record(), &records);
        let expression = match &fact {
            Fact::Size(_) => format!("sizeof({ty})"),
            Fact::Align(_) => format!("_Alignof({ty})"),
            Fact::Offset(_, field) => format!("offsetof({ty}, {})", c_field(field)),
        };
        writeln!(
            program,
            "    printf(\"%s %zu\\n\", \"{label}\", (size_t)({expression}));"
        )?;
        checked += 1;
    }
    program.push_str("    return 0;\n}\n");
    let output = compile_and_run(cx, "layouts", &program)?;
    Ok(Outcome {
        summary: format!("{checked} sizes, alignments, and field offsets match the C compiler's"),
        problems: compare(&facts, &output, |label| Fact::parse(label).is_some()),
    })
}

/// Check 5: every integer and string constant's value, and each integer's size and signedness.
pub fn constants(cx: &Context) -> Result<Outcome> {
    let constants = constant_values(&generated(cx)?)?;
    let mut program = String::from("#include <stdio.h>\n#include <string.h>\n");
    let headers = Headers::new(&cx.root, &cx.work.join("headers"))?;
    writeln!(program, "#include \"{}\"\n", headers.wrapper.display())?;
    program.push_str(
        "#define I(name) printf(\"%s %zu %d %lld %llu\\n\", #name, sizeof(name), \
         (name) * 0 - 1 < 0, (long long)(name), (unsigned long long)(name))\n\
         #define S(name) string(#name, name, sizeof(name))\n\n\
         static void string(const char *name, const char *value, size_t size)\n{\n    \
         printf(\"%s\", name);\n    for (size_t i = 0; i < size; i++)\n        \
         printf(\" %02x\", (unsigned char)value[i]);\n    printf(\"\\n\");\n}\n\n\
         int main(void)\n{\n",
    );
    for (name, value) in &constants {
        match value {
            Constant::Integer { .. } => writeln!(program, "    I({name});")?,
            Constant::String(_) => writeln!(program, "    S({name});")?,
        }
    }
    program.push_str("    return 0;\n}\n");
    let output = compile_and_run(cx, "constants", &program)?;

    let mut problems = Vec::new();
    let printed: BTreeMap<&str, &str> = output
        .lines()
        .filter_map(|line| line.split_once(' '))
        .collect();
    for (name, value) in &constants {
        let Some(line) = printed.get(name.as_str()) else {
            problems.push(format!("{name}: the C program printed nothing"));
            continue;
        };
        if let Some(problem) = value.check(line) {
            problems.push(format!("{name}: {problem}"));
        }
    }
    let strings = constants
        .values()
        .filter(|c| matches!(c, Constant::String(_)))
        .count();
    Ok(Outcome {
        summary: format!(
            "{} integer and {strings} string constants match the C compiler's",
            constants.len() - strings
        ),
        problems,
    })
}

/// The generated `rustssl-abi` source for the host target.
fn generated(cx: &Context) -> Result<syn::File> {
    let path = cx
        .root
        .join("crates/rustssl-abi/src/generated")
        .join(format!("{}.rs", cx.target.module));
    Ok(syn::parse_file(&fs::read_to_string(&path)?)?)
}

/// `-I` flags for the vendored headers, with the host's `configuration.h`.
fn include_flags(cx: &Context) -> Vec<PathBuf> {
    let config = cx.abi.join("config").join(cx.target.configure);
    vec!["-I".into(), config, "-I".into(), cx.abi.join("include")]
}

/// Compiles a generated C program with the vendored headers and returns what it prints.
fn compile_and_run(cx: &Context, name: &str, source: &str) -> Result<String> {
    let dir = cx.work.join(name);
    fs::create_dir_all(&dir)?;
    let file = dir.join(format!("{name}.c"));
    let exe = dir.join(name);
    fs::write(&file, source)?;
    // Warnings are off: the programs compare unsigned values with zero on purpose.
    run_output(
        cc().args(include_flags(cx))
            .args(["-std=gnu11", "-w", "-o"])
            .arg(&exe)
            .arg(&file),
    )?;
    run_output(&mut Command::new(&exe))
}

/// The labels and values of the layout assertions bindgen generated:
/// `["Size of buf_mem_st"][size_of::<buf_mem_st>() - 32usize];`.
fn layout_facts(file: &syn::File) -> Result<Vec<(String, u64)>> {
    let mut facts = Vec::new();
    for item in &file.items {
        let syn::Item::Const(constant) = item else {
            continue;
        };
        let syn::Expr::Block(block) = &*constant.expr else {
            continue;
        };
        for statement in &block.block.stmts {
            let syn::Stmt::Expr(syn::Expr::Index(index), _) = statement else {
                continue;
            };
            let (syn::Expr::Array(label), syn::Expr::Binary(difference)) =
                (&*index.expr, &*index.index)
            else {
                continue;
            };
            let (
                Some(syn::Expr::Lit(syn::ExprLit {
                    lit: syn::Lit::Str(label),
                    ..
                })),
                syn::Expr::Lit(syn::ExprLit {
                    lit: syn::Lit::Int(value),
                    ..
                }),
            ) = (label.elems.first(), &*difference.right)
            else {
                continue;
            };
            facts.push((label.value(), value.base10_parse()?));
        }
    }
    Ok(facts)
}

/// One layout fact, by the Rust names bindgen gave the record and field.
enum Fact<'a> {
    Size(&'a str),
    Align(&'a str),
    Offset(&'a str, &'a str),
}

impl<'a> Fact<'a> {
    /// Parses a label, skipping records and fields C can't name: bindgen's names for anonymous
    /// records (`__bindgen_ty_1`), bitfield storage, placeholders, and the implementation's
    /// own records, whose names start with `__` (x86_64's `__va_list_tag`, behind `va_list`).
    fn parse(label: &'a str) -> Option<Self> {
        let fact = if let Some(record) = label.strip_prefix("Size of ") {
            Fact::Size(record)
        } else if let Some(record) = label.strip_prefix("Alignment of ") {
            Fact::Align(record)
        } else {
            let (record, field) = label.strip_prefix("Offset of field: ")?.split_once("::")?;
            if field.starts_with("_bitfield")
                || field.starts_with("__bindgen")
                || field == "_address"
            {
                return None;
            }
            Fact::Offset(record, field)
        };
        let record = fact.record();
        (!record.contains("__bindgen") && !record.starts_with("__")).then_some(fact)
    }

    fn record(&self) -> &'a str {
        match self {
            Fact::Size(record) | Fact::Align(record) | Fact::Offset(record, _) => record,
        }
    }
}

/// The struct and union tags in preprocessed C, as (tag, keyword).
fn record_tags(text: &str) -> BTreeMap<String, &'static str> {
    let mut tags = BTreeMap::new();
    let words: Vec<(usize, &str)> = word_positions(text);
    for pair in words.windows(2) {
        let [(start, keyword), (next, name)] = pair else {
            continue;
        };
        let keyword = match *keyword {
            "struct" => "struct",
            "union" => "union",
            _ => continue,
        };
        // Only whitespace may separate the keyword from its tag.
        let between = text.get(start + keyword.len()..*next).unwrap_or("x");
        if between.chars().all(char::is_whitespace) {
            tags.insert((*name).to_owned(), keyword);
        }
    }
    tags
}

/// Every identifier-like word in `text` with its byte offset.
fn word_positions(text: &str) -> Vec<(usize, &str)> {
    let mut words = Vec::new();
    let mut start = None;
    for (i, c) in text.char_indices().chain([(text.len(), ' ')]) {
        let word = c.is_ascii_alphanumeric() || c == '_';
        match (word, start) {
            (true, None) => start = Some(i),
            (false, Some(s)) => {
                words.push((s, text.get(s..i).unwrap_or_default()));
                start = None;
            }
            _ => {}
        }
    }
    words
}

/// How C names the record bindgen called `name`: by its tag, or else by its typedef. bindgen
/// names a record declared inside another `<parent>_<tag>`, while C knows it by its own tag
/// (the `union lh_X509_dummy` inside `struct lhash_st_X509`).
fn c_type(name: &str, tags: &BTreeMap<String, &str>) -> String {
    if let Some(keyword) = tags.get(name) {
        return format!("{keyword} {name}");
    }
    for (tag, keyword) in tags {
        let parent = name
            .strip_suffix(tag.as_str())
            .and_then(|p| p.strip_suffix('_'));
        if parent.is_some_and(|p| tags.contains_key(p)) {
            return format!("{keyword} {tag}");
        }
    }
    name.to_owned()
}

/// The C name of a field: bindgen appends `_` to names that are Rust keywords (`type_`).
fn c_field(field: &str) -> &str {
    const KEYWORDS: &[&str] = &[
        "as", "async", "await", "box", "break", "const", "continue", "crate", "dyn", "else",
        "enum", "extern", "false", "fn", "for", "gen", "if", "impl", "in", "let", "loop", "match",
        "mod", "move", "mut", "priv", "pub", "ref", "return", "self", "static", "struct", "super",
        "trait", "true", "try", "type", "typeof", "unsafe", "use", "where", "while", "yield",
    ];
    match field.strip_suffix('_') {
        Some(name) if KEYWORDS.contains(&name) => name,
        _ => field,
    }
}

/// The problems between the Rust `facts` and the C program's `output` (`label value` lines).
fn compare(facts: &[(String, u64)], output: &str, wanted: impl Fn(&str) -> bool) -> Vec<String> {
    let printed: BTreeMap<&str, &str> = output
        .lines()
        .filter_map(|line| line.rsplit_once(' '))
        .collect();
    let mut problems = Vec::new();
    for (label, value) in facts.iter().filter(|(label, _)| wanted(label)) {
        match printed.get(label.as_str()) {
            Some(c) if c.parse::<u64>().ok() == Some(*value) => {}
            Some(c) => problems.push(format!("{label}: rustssl-abi {value}, C {c}")),
            None => problems.push(format!("{label}: the C program printed nothing")),
        }
    }
    problems
}

/// A constant's value in `rustssl-abi`.
#[derive(Debug, PartialEq)]
enum Constant {
    /// With the size and signedness of its C type, if it's a C integer type (enum constants
    /// have the enum's alias as their type).
    Integer {
        ty: Option<(usize, bool)>,
        value: i128,
    },
    /// The bytes, with the terminating NUL.
    String(Vec<u8>),
}

impl Constant {
    /// Compares with what the C program printed after the name: `size signed value unsigned`
    /// for an integer, the bytes in hex for a string.
    fn check(&self, printed: &str) -> Option<String> {
        match self {
            Constant::String(bytes) => {
                let expected: Vec<String> = bytes.iter().map(|b| format!("{b:02x}")).collect();
                let expected = expected.join(" ");
                (printed != expected).then(|| format!("rustssl-abi {expected}, C {printed}"))
            }
            Constant::Integer { ty, value } => {
                let fields: Vec<&str> = printed.split(' ').collect();
                let [size, signed, as_signed, as_unsigned] = fields.as_slice() else {
                    return Some(format!("unexpected output {printed:?}"));
                };
                let c_signed = *signed == "1";
                let c_value = if c_signed { as_signed } else { as_unsigned };
                let mut problems = Vec::new();
                if c_value.parse::<i128>().ok() != Some(*value) {
                    problems.push(format!("rustssl-abi {value}, C {c_value}"));
                }
                if let Some((rust_size, rust_signed)) = ty {
                    if size.parse::<usize>().ok() != Some(*rust_size) {
                        problems.push(format!("{rust_size}-byte type, C {size} bytes"));
                    }
                    if *rust_signed != c_signed {
                        problems.push(format!(
                            "{} type, C {}",
                            if *rust_signed { "signed" } else { "unsigned" },
                            if c_signed { "signed" } else { "unsigned" }
                        ));
                    }
                }
                (!problems.is_empty()).then(|| problems.join("; "))
            }
        }
    }
}

/// Every `pub const` with a literal value in the generated file.
fn constant_values(file: &syn::File) -> Result<BTreeMap<String, Constant>> {
    let mut constants = BTreeMap::new();
    for item in &file.items {
        let syn::Item::Const(constant) = item else {
            continue;
        };
        if constant.ident == "_" {
            continue;
        }
        let value = match &*constant.expr {
            syn::Expr::Lit(syn::ExprLit {
                lit: syn::Lit::CStr(text),
                ..
            }) => Constant::String(text.value().into_bytes_with_nul()),
            expr => match integer(expr)? {
                Some(value) => Constant::Integer {
                    ty: integer_type(&constant.ty),
                    value,
                },
                None => continue,
            },
        };
        constants.insert(constant.ident.to_string(), value);
    }
    Ok(constants)
}

/// An integer literal, possibly negated.
fn integer(expr: &syn::Expr) -> Result<Option<i128>> {
    Ok(match expr {
        syn::Expr::Lit(syn::ExprLit {
            lit: syn::Lit::Int(value),
            ..
        }) => Some(value.base10_parse()?),
        syn::Expr::Unary(syn::ExprUnary {
            op: syn::UnOp::Neg(_),
            expr,
            ..
        }) => integer(expr)?.map(|v| -v),
        _ => None,
    })
}

/// The size and signedness of a C integer type named by its `core::ffi` alias, on this host.
fn integer_type(ty: &syn::Type) -> Option<(usize, bool)> {
    use core::ffi::{
        c_char, c_int, c_long, c_longlong, c_schar, c_short, c_uchar, c_uint, c_ulong, c_ulonglong,
        c_ushort,
    };
    use std::mem::size_of;
    let syn::Type::Path(path) = ty else {
        return None;
    };
    let name = path.path.segments.last()?.ident.to_string();
    Some(match name.as_str() {
        "c_char" => (size_of::<c_char>(), c_char::MIN != 0),
        "c_schar" => (size_of::<c_schar>(), true),
        "c_uchar" => (size_of::<c_uchar>(), false),
        "c_short" => (size_of::<c_short>(), true),
        "c_ushort" => (size_of::<c_ushort>(), false),
        "c_int" => (size_of::<c_int>(), true),
        "c_uint" => (size_of::<c_uint>(), false),
        "c_long" => (size_of::<c_long>(), true),
        "c_ulong" => (size_of::<c_ulong>(), false),
        "c_longlong" => (size_of::<c_longlong>(), true),
        "c_ulonglong" => (size_of::<c_ulonglong>(), false),
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const GENERATED: &str = r#"
        pub const A: core::ffi::c_int = 16;
        pub const B: core::ffi::c_ulonglong = 0x80000850;
        pub const C: some_enum = -1;
        pub const D: &core::ffi::CStr = c"sha256";
        pub type some_enum = core::ffi::c_int;
        const _: () = {
            ["Size of buf_mem_st"][::core::mem::size_of::<buf_mem_st>() - 32usize];
            ["Offset of field: asn1_string_st::type_"]
                [::core::mem::offset_of!(asn1_string_st, type_) - 4usize];
            ["Size of x__bindgen_ty_1"][::core::mem::size_of::<x__bindgen_ty_1>() - 8usize];
        };
    "#;

    #[test]
    fn reads_the_generated_file() {
        let file = syn::parse_file(GENERATED).unwrap();
        let constants = constant_values(&file).unwrap();
        assert_eq!(
            constants["A"],
            Constant::Integer {
                ty: Some((4, true)),
                value: 16
            }
        );
        assert_eq!(
            constants["B"],
            Constant::Integer {
                ty: Some((8, false)),
                value: 0x8000_0850
            }
        );
        assert_eq!(
            constants["C"],
            Constant::Integer {
                ty: None,
                value: -1
            }
        );
        assert_eq!(constants["D"], Constant::String(b"sha256\0".to_vec()));
        assert_eq!(
            layout_facts(&file).unwrap(),
            [
                ("Size of buf_mem_st".to_owned(), 32),
                ("Offset of field: asn1_string_st::type_".to_owned(), 4),
                ("Size of x__bindgen_ty_1".to_owned(), 8),
            ]
        );
    }

    #[test]
    fn constants_compare_value_size_and_sign() {
        let int = Constant::Integer {
            ty: Some((4, true)),
            value: -1,
        };
        assert_eq!(int.check("4 1 -1 18446744073709551615"), None);
        assert!(
            int.check("4 0 -1 4294967295")
                .unwrap()
                .contains("signed type, C unsigned")
        );
        assert!(
            int.check("8 1 -1 18446744073709551615")
                .unwrap()
                .contains("4-byte type")
        );
        let unsigned = Constant::Integer {
            ty: Some((8, false)),
            value: 0x8000_0850,
        };
        assert_eq!(unsigned.check("8 0 2147485776 2147485776"), None);
        let enumerator = Constant::Integer { ty: None, value: 3 };
        assert_eq!(enumerator.check("4 1 3 3"), None);
        assert!(enumerator.check("4 1 4 4").is_some());
        let string = Constant::String(b"ab\0".to_vec());
        assert_eq!(string.check("61 62 00"), None);
        assert!(string.check("61 63 00").is_some());
    }

    #[test]
    fn layout_labels_and_c_names() {
        assert!(matches!(
            Fact::parse("Size of buf_mem_st"),
            Some(Fact::Size("buf_mem_st"))
        ));
        assert!(matches!(
            Fact::parse("Offset of field: asn1_string_st::type_"),
            Some(Fact::Offset("asn1_string_st", "type_"))
        ));
        assert!(Fact::parse("Size of x__bindgen_ty_1").is_none());
        assert!(Fact::parse("Size of __va_list_tag").is_none());
        assert!(Fact::parse("Offset of field: __va_list_tag::gp_offset").is_none());
        assert!(Fact::parse("Offset of field: x::_bitfield_1").is_none());
        assert_eq!(c_field("type_"), "type");
        assert_eq!(c_field("length"), "length");
        assert_eq!(c_field("data_"), "data_");

        let tags = record_tags(
            "struct buf_mem_st { size_t length; };\ntypedef struct { struct buf_mem_st *b; } \
             ANON;\nunion  u_st { int i; };\nsizeof(struct\nbio_st)",
        );
        assert_eq!(tags.get("buf_mem_st"), Some(&"struct"));
        assert_eq!(tags.get("u_st"), Some(&"union"));
        assert_eq!(tags.get("bio_st"), Some(&"struct"));
        assert!(!tags.contains_key("size_t"));
        assert_eq!(c_type("buf_mem_st", &tags), "struct buf_mem_st");
        assert_eq!(c_type("ANON", &tags), "ANON");
        let nested = record_tags("struct lhash_st_X { union lh_X_dummy { void *d; } dummy; };");
        assert_eq!(c_type("lhash_st_X_lh_X_dummy", &nested), "union lh_X_dummy");

        let facts = [("Size of a".to_owned(), 8), ("Size of b".to_owned(), 4)];
        assert!(compare(&facts, "Size of a 8\nSize of b 4\n", |_| true).is_empty());
        assert_eq!(compare(&facts, "Size of a 16\n", |_| true).len(), 2);
    }
}
